args.sql:
SELECT COUNT(*) as total, 
       SUM(CASE WHEN (em.env_metrics::jsonb -> 'temperature' ->> 'excursion_count')::int > 0 THEN 1 ELSE 0 END) as problem_shipments
FROM environmentalmonitoring em;

SELECT AVG((em.env_metrics::jsonb -> 'temperature' ->> 'avg_c')::float) AS avg_temperature_effect
FROM environmentalmonitoring em
WHERE (em.env_metrics::jsonb -> 'temperature' ->> 'excursion_count')::int > 0;

SELECT 
    CASE WHEN ir.incident_risk_record::jsonb -> 'risk' ->> 'risk_level' = 'High' THEN 1 ELSE 0 END as high_risk_count
FROM incidentandriskmanagement ir;

SELECT ROUND(CAST(AVG(
    (-83144.0 / 8.3144) / LN(
        (EXP(-83144.0 / (8.3144 * (CAST(em.env_metrics::jsonb -> 'temperature' ->> 'avg_c' AS float) + 273.15))) +
         EXP(-83144.0 / (8.3144 * (CAST(em.env_metrics::jsonb -> 'temperature' ->> 'max_c' AS float) + 273.15))) +
         EXP(-83144.0 / (8.3144 * (CAST(em.env_metrics::jsonb -> 'temperature' ->> 'min_c' AS float) + 273.15)))) / 3.0
    ) - 273.15
) AS numeric), 2) AS avg_temperature_effect
FROM environmentalmonitoring em
WHERE (em.env_metrics::jsonb -> 'temperature' ->> 'excursion_count')::int > 0;

SELECT ROUND(CAST(AVG(
    (-83144.0 / 8.3144) / LN(
        (EXP(-83144.0 / (8.3144 * (CAST(em.env_metrics::jsonb -> 'temperature' ->> 'avg_c' AS float) + 273.15))) +
         EXP(-83144.0 / (8.3144 * (CAST(em.env_metrics::jsonb -> 'temperature' ->> 'max_c' AS float) + 273.15))) +
         EXP(-83144.0 / (8.3144 * (CAST(em.env_metrics::jsonb -> 'temperature' ->> 'min_c' AS float) + 273.15)))) / 3.0
    ) - 273.15
) AS numeric), 2) AS avg_temperature_effect
FROM environmentalmonitoring em
WHERE (em.env_metrics::jsonb -> 'temperature' ->> 'excursion_count')::int > 0;

SELECT ROUND(CAST(AVG((em.env_metrics::jsonb -> 'temperature' ->> 'avg_c')::float) AS numeric), 2) AS avg_temperature_effect
FROM environmentalmonitoring em
WHERE (em.env_metrics::jsonb -> 'temperature' ->> 'excursion_count')::int > 0;

SELECT ROUND(CAST(AVG((em.env_metrics::jsonb -> 'temperature' ->> 'excursion_duration_min')::float) AS numeric), 2) AS avg_temperature_effect
FROM environmentalmonitoring em
WHERE (em.env_metrics::jsonb -> 'temperature' ->> 'excursion_count')::int > 0;

SELECT ROUND(CAST(AVG((em.env_metrics::jsonb -> 'temperature' ->> 'alarm_count')::float) AS numeric), 2) AS avg_temperature_effect
FROM environmentalmonitoring em
WHERE (em.env_metrics::jsonb -> 'temperature' ->> 'excursion_count')::int > 0;

SELECT AVG(
    (-83144.0 / 8.3144) / LN(EXP(-83144.0 / (8.3144 * (CAST(em.env_metrics::jsonb -> 'temperature' ->> 'avg_c' AS float) + 273.15)))) - 273.15
) AS avg_mkt_single
FROM environmentalmonitoring em
WHERE (em.env_metrics::jsonb -> 'temperature' ->> 'excursion_count')::int > 0;

SELECT ROUND(CAST(AVG((em.env_metrics::jsonb -> 'temperature' ->> 'max_c')::float - (em.env_metrics::jsonb -> 'temperature' ->> 'min_c')::float) AS numeric), 2) AS avg_temp_effect
FROM environmentalmonitoring em
WHERE (em.env_metrics::jsonb -> 'temperature' ->> 'excursion_count')::int > 0;

SELECT ROUND(CAST(AVG((em.env_metrics::jsonb -> 'temperature' ->> 'excursion_count')::float) AS numeric), 2) AS avg_temperature_effect
FROM environmentalmonitoring em
WHERE (em.env_metrics::jsonb -> 'temperature' ->> 'excursion_count')::int > 0;
